ALTER TABLE public.company_delivery_places ADD COLUMN supplier_record_id uuid REFERENCES public.supplier_records(id);
DROP INDEX public.company_delivery_places_company_text_unique;
CREATE UNIQUE INDEX company_delivery_places_company_supplier_text_unique ON public.company_delivery_places (company_id, supplier_record_id, lower(regexp_replace(btrim(text), '\s+', ' ', 'g'))) NULLS NOT DISTINCT;
DROP POLICY "Indicazioni consegna create dai membri" ON public.company_delivery_places;
CREATE POLICY "Indicazioni consegna create dai membri" ON public.company_delivery_places FOR INSERT TO authenticated WITH CHECK (public.is_company_member(company_id) AND created_by = auth.uid() AND supplier_record_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.supplier_records sr WHERE sr.id = company_delivery_places.supplier_record_id AND sr.buyer_company_id = company_id));
CREATE OR REPLACE FUNCTION public.save_shopping_list_delivery_place(_list_id uuid, _supplier_record_id uuid, _text text) RETURNS public.company_delivery_places LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_company uuid; v_text text; v_row public.company_delivery_places; BEGIN SELECT company_id INTO v_company FROM shopping_lists WHERE id = _list_id; IF v_company IS NULL OR NOT is_company_member(v_company) THEN RAISE EXCEPTION 'Lista non accessibile'; END IF; IF NOT EXISTS (SELECT 1 FROM supplier_records WHERE id = _supplier_record_id AND buyer_company_id = v_company) THEN RAISE EXCEPTION 'Fornitore non valido per questa azienda'; END IF; v_text := regexp_replace(btrim(_text), '\s+', ' ', 'g'); IF length(v_text) < 1 OR length(v_text) > 300 THEN RAISE EXCEPTION 'Il testo deve contenere da 1 a 300 caratteri'; END IF; INSERT INTO company_delivery_places (company_id, supplier_record_id, text, created_by) VALUES (v_company, _supplier_record_id, v_text, auth.uid()) ON CONFLICT DO NOTHING RETURNING * INTO v_row; IF v_row.id IS NULL THEN SELECT * INTO v_row FROM company_delivery_places WHERE company_id = v_company AND supplier_record_id = _supplier_record_id AND lower(regexp_replace(btrim(text), '\s+', ' ', 'g')) = lower(v_text); END IF; RETURN v_row; END; $$;
REVOKE ALL ON FUNCTION public.save_shopping_list_delivery_place(uuid, uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_shopping_list_delivery_place(uuid, uuid, text) TO authenticated, service_role;
REVOKE EXECUTE ON FUNCTION public.save_shopping_list_delivery_place(uuid, text) FROM authenticated, service_role;